def classify(r):
    code = r.status_code
    if 200 <= code < 300:
        return "ok"
    if code == 401:
        return "refresh token, then retry once"
    if code == 429:
        wait = r.headers.get("Retry-After", "a few")
        return f"rate limited: wait {wait} seconds and retry"
    if code in (500, 502, 503, 504):
        return "server trouble: retry with backoff"
    if 400 <= code < 500:
        return f"our request is wrong, do not retry: {r.text[:200]}"
    return "unexpected"

import time

def pause_if_low(r, min_left=5):
    """Return how many seconds to wait before the API starts answering 429."""
    h = r.headers
    left = h.get("X-RateLimit-Remaining") or h.get("RateLimit-Remaining")
    reset = h.get("X-RateLimit-Reset") or h.get("RateLimit-Reset")
    if left is None or reset is None or int(left) > min_left:
        return 0
    reset = int(reset)
    # X-RateLimit-Reset is often a Unix time; RateLimit-Reset is seconds from now
    wait = reset - int(time.time()) if reset > 1_000_000_000 else reset
    return max(wait, 0)

