import requests

class RetryableError(Exception):
    """Error worth retrying: rate limit, server error, timeout."""

def classify(resp: requests.Response) -> None:
    if resp.status_code == 429:                   # rate limited
        raise RetryableError("429", resp.headers.get("Retry-After"))
    if 500 <= resp.status_code < 600:             # server problem
        raise RetryableError(str(resp.status_code))
    resp.raise_for_status()                       # other 4xx: a real bug, fail

def get(session: requests.Session, url: str, params: dict) -> dict:
    try:
        resp = session.get(url, params=params, timeout=(3, 10))  # connect, read
    except (requests.Timeout, requests.ConnectionError) as e:
        raise RetryableError("network") from e
    classify(resp)
    return resp.json()


# 401: refresh the OAuth token once, then give up
import requests

class AuthFailed(Exception):
    """Credentials are wrong even after a refresh: stop and alert a person."""

def get_with_refresh(session, url, params, tokens):
    """401 once: refresh the OAuth access token and retry. 401 twice: stop."""
    for attempt in (1, 2):
        headers = {"Authorization": f"Bearer {tokens.access_token()}"}
        resp = session.get(url, params=params, headers=headers, timeout=(3, 10))
        if resp.status_code != 401:
            resp.raise_for_status()
            return resp.json()
        if attempt == 1:
            tokens.refresh()          # expired access token: get a new one
    raise AuthFailed("401 after token refresh: check the client secret or its scopes")

