# Honouring Retry-After (seconds or an HTTP date) with a custom wait
import email.utils, time
import requests
from tenacity import (retry, stop_after_attempt, wait_exponential_jitter,
                      retry_if_exception_type)

class RetryableError(Exception):
    def __init__(self, reason, retry_after=None):
        super().__init__(reason)
        self.retry_after = retry_after          # raw header value, or None

def parse_retry_after(value, now=None):
    """Retry-After is either seconds ("120") or an HTTP date."""
    if value is None:
        return None
    if value.strip().isdigit():
        return float(value)
    when = email.utils.parsedate_to_datetime(value)   # "Wed, 30 Sep 2026 10:00:00 GMT"
    now = time.time() if now is None else now
    return max(0.0, when.timestamp() - now)

backoff = wait_exponential_jitter(initial=1, max=30)

def wait_retry_after_or_backoff(retry_state):
    err = retry_state.outcome.exception()
    seconds = parse_retry_after(getattr(err, "retry_after", None))
    if seconds is not None:
        return min(seconds, 300)                # obey the server, but cap it
    return backoff(retry_state)                 # otherwise normal backoff + jitter

@retry(wait=wait_retry_after_or_backoff,
       stop=stop_after_attempt(5),
       retry=retry_if_exception_type(RetryableError),
       reraise=True)
def fetch_page(session, cursor):
    resp = session.get("https://api.example-crm.com/v1/orders",
                       params={"cursor": cursor, "limit": 500}, timeout=(3, 10))
    if resp.status_code == 429:
        raise RetryableError("429", resp.headers.get("Retry-After"))
    if resp.status_code >= 500:
        raise RetryableError(str(resp.status_code))
    resp.raise_for_status()
    return resp.json()

print(parse_retry_after("120"))
print(parse_retry_after("Wed, 30 Sep 2026 10:00:30 GMT",
                        now=email.utils.parsedate_to_datetime(
                            "Wed, 30 Sep 2026 10:00:00 GMT").timestamp()))
# 120.0
# 30.0

